  cube(f'SA{idx}_D14WestFloorCrossbeam_{v}',[xlo,88.1,zz-.1],[-85.7,88.28,zz+.1],'D14_outer_floor_extension_from_existing_pier');supports.append({**toe,'reused_existing_pier':True,'source_model':F['model_file'],'new_pier':False});original=next(q for q in F['parts']if q['name']==toe['name'].replace('FloorPier','FloorCrossbeam'));assert np.min(original['verts'],axis=0)[0]==-85.9;joints.append({'name':parts[-1]['name'],'existing_model':F['model_file'],'existing_mesh':original['name'],'overlap_bounds':[[-85.9,88.1,zz-.1],[-85.7,88.28,zz+.1]],'basis':'Existing exact crossbeam/pier retained and extended; no duplicate pier or load certificate'})
