 original=next(q for q in C['parts']if q['name']==f'SA_D15_{side}WestGuard');assert np.min(original['verts'],axis=0).tolist()==[-86.05,93,lo] and np.max(original['verts'],axis=0).tolist()==[-85.98,94.1,hi];intervals=[];at=lo
 for a,b in openings:assert at<a<b<hi;intervals.append([at,a]);at=b
 intervals.append([at,hi])
 for n,(a,b)in enumerate(intervals):cube(f'SA_D15_{side}FifthWestGuardSegment_{n}',[-86.05,93,a],[-85.98,94.1,b],'retained_west_guard_outside_new_entries')
 guards.append({'source_name':original['name'],'original_part':original,'entry_openings':openings,'retained_intervals':intervals,'source_model':C['model_file']})
